def compute_q_mod_d(n, totient, m):
    # Use Lucas Theorem to compute large exponentiation modulo a prime
    numerator = denominator = 1
    for n2, q2 in enumerate(bin(n)[3:], 2):
        if int(q2):
            numerator = (numerator * m ** int(n2)) % totient
        if int(q2 == '1'):
            denominator = (denominator * m ** int(n2)) % totient

