        return False
    compressed_t = compress_string(t)
    common_substrings = []
    for i in range(len(compressed_t) + 1):
        for j in range(len(s) - i + 1):
            substring = s[j:j+i]
            if substring in compressed_t and len(compressed_t) - len(compressed_t[j:j+i]) <= (x + 1):
