from typing import List

def min_cost_sort(N: int, P: List[int]) -> (int, int, List[List[int]]):
    # Copy of permutation to ensure we don't modify the original array
    perm = P[:]

    def sort_operations(perm):
        operations = []
        while not is_sorted(perm):
            _, i, j = find_min_swap(perm)
            operations.append([i, j])
            perm[i], perm[j] = perm[j], perm[i]
        return operations, sum(map(abs, map(lambda x, y: y - x, index_dist).values()))

    def is_sorted(perm):
        return sorted(perm) == perm

    def find_min_swap(perm):
        min_cost = float('inf')
        best_operations = None
        min_swap_index = perm.index(min(perm))
        for i in range(len(perm)):
            if i == min_swap_index:
                continue
            for j in range(len(perm)):
                if j == min_swap_index or i == j:
                    continue
                cost = abs(i - j)
                if cost < min_cost and is_sorted(perm[:i] + perm[i:j] + perm[i+1:j+1] + perm[j+1:]):
                    min_cost = cost
                    best_operations = [i, j]
        return min_cost, best_operations[0], best_operations[1]

    def index_dist(perm):
        return {i: j for i, j in enumerate(perm)}

    operations = sort_operations(perm)
    cost, swaps = operations
    return cost, swaps, operations

