def getNextBoard(board, start, end):
    # Create a new board with updated positions
    x1 = (start[0] + end[0]) // 2
    y1 = (start[1] + end[1]) // 2
    new_board = board[:]
    for i in range(x1 - 1, x1 + 2):
        for j in range(y1 - 1, y1 + 2):
            new_board[i][j] = -1
    for i, j in [(x1 - 1, y1), (x1 - 1, y1 - 1), (x1 - 1, y1 + 1), 
                 (x1 + 1, y1), (x1, y1 - 1), (x1, y1 + 1)]:
        if board[i][j] == -1:
            new_board[i][j] = 'R'
        else:
            new_board[i][j] = 'B'
    for i in range(x1 - 1, x1 + 2):
