def get_cake_area(cakes):
    n = len(cakes)
    h = cakes[1][1] - cakes[0][1]
    d = sqrt(sum([h * cakes[k][1] + (k + 1) * (cakes[k+1][1] - cakes[k][1])**2
                  for k in range(n - 1)]))
