    for index, (x, y) in enumerate(cakes[1:]):
        if x > min_coords[0]:
            min_index = index
            min_coords = (x, y)
        elif x + y > min_coords[0] and x + y > y and y > cakes[min_index][1]:
            min_index = index
            min_coords = (x, y)
    return (min_index, min_coords)

