import sys

def find_cut(n, m, original_width, original_height, cuts):
    new_width = (original_width + 1) // 2
    new_height = (original_height + 1) // 2
    for x_start, x_end, y_start, y_end in cuts:
        if x_start <= new_width:
            new_width = max(new_width, x_start)
        if x_end >= n - new_width:
            new_width = max(new_width, n - x_end)
        if y_start <= new_height:
            new_height = max(new_height, y_start)
        if y_end >= m - new_height:
            new_height = max(new_height, m - y_end)
    return new_width, new_height

def determine_winner(n, m, k, points):
    cuts = []
    for i in range(k):
        xbi, ybi, xei, yei = map(int, points[i].split())
        if xbi <= xei:
            cuts.append((xbi, xei, ybi, yei))
        else:
            cuts.append((xei, xbi, ybi, yei))

    width, height = find_cut(n, m, 0, 0, cuts)

    if width >= height:
        return "FIRST\n", (2, 1, 2, 1)
    else:
        width //= 2
        height //= 2
        return "SECOND\n", (width, height, 3, 4)

