    """Calculate n! modulo MOD"""
    return pow(n, (MOD+1)//2, MOD)

def inv_mod_enhanced(n):
    """Calculate the modular inverse of n modulo MOD"""
    return pow(n, MOD-2, MOD)

def nth_remainder(n, m, k):
    """Calculate the nth entry without calculus, modulo MOD"""
    x = []
    for i in range(m-1, -1, -1):
        x.append(factorial(m-i))
        x.append((m-i) * mod_inverse(factorial(m-1-i), MOD) for m_i in range(m-i+1, m+1))
