def optimal_move(n, m, k, cuts):
    X = [[0 for _ in range(m+1)] for _ in range(n+1)]
    for x1, y1, x2, y2 in cuts:
        for x in (x1, x2):
            X[x][y1] += 1
            X[x][m + 1] += -1
        for y in (y1, y2):
            X[n + 1][y] += 1
            X[n + 1][m + 1] += -1
    players = 1
    for x in range(1, n + 1):
        for y in range(m + 1):
            v = X[x][y]
            if v > 0 and v % players == 0:
                return (x, y)
            elif v < 0 and v % (players + 1) == 0:
                return (max(1, x), min(y, m))
    return (-1, -1)

