def play_game(n, stacks):
    total_pairs = sum(len(stack) * 2 for stack in stacks)
    expected_ef = sum(stacks[i].a1 - stacks[(i+1) % len(stacks)].b1 + (-1)**(i % 2) for i in range(n))
    return total_pairs - expected_ef

def game(stacks):
    n = len(stacks)
    result = []
    heapq.heappush(result, (stacks[0].a1 - stacks[1].b1, 0))
    for i in range(1, n):
        while 1:
            pf, sf = heapq.heappop(result)
            df = dfs(stacks, i - 1, sf)
            pf2 = sum(stacks[0].a2 - stacks[i].a1 for i in range(n)) - pf - df
            if pf2 > 0:
                pf3 = (pf + pf2 - n) // 2
                if pf3 < 0:
                    pf3 = 0
                break
            heapq.heappush(result, (pf - ((n - i - 1) * stacks[0].a1 + i * (stacks[i].a1 + stacks[n - i].a1)) // (n - i), i))
    return result[-1][0]

