from collections import defaultdict

def build_str_too_slow(max_len, t):
    # Function to generate all unique substrings of `max_len` from `t`
    def get_substrings(max_len):
        dp = {}
        for i in range(max_len, -1, -1):
            for j in range(len(t) - (max_len - i)):
                substring = t[j:j+i+1]
                if substring in dp:
                    dp[substring] += 1
                else:
                    dp[substring] = 1
        return sorted(dp.keys(), key=lambda x: -len(x))

    # Generate substrings of all possible lengths
    substrings = set()
    for i in range(1, max_len-1):
        substrings |= set(a + b for a in get_substrings(i) for b in get_substrings(max_len-i-1))

    # Create a list where each index corresponds to a substring in `substrings`
    l = {}
    for i in range(len(t)):
        for j in range(i, len(t)):
            substring = t[i:j+1]
            if substring in substrings:
                if substring in l:
                    l[substring].append(j)
                else:
                    l[substring] = [j]

    # Find a substring that can have up to 2 substrings longer than 2*t(len of t)
    for s in substrings:
        if (max(l[s][::-1]) - min(l[s][::-1])) <= (2 * len(t) - 2):
            return len(s)

    # If no such substring found, return the largest valid substring length
    for s in substrings:
        if (max(l[s][::-1]) - min(l[s][::-1])) < (2 * len(t) - 2):
            return len(s)

    return len(t)


# Tool function to check the solution for given inputs
def check_solution():
    assert build_str_too_slow(5, 'ABCCAD') == 5
    assert build_str_too_slow(5, 'AAABACADBABBBCBDCACBCCCDDDBDCDD') == 4

check_solution()
