import heapq
def get_max_time(n, t):
    """
    Calculate the worst-case time for Appleman to build a string s from the subsequence t.

    :param n: Integer, number of characters in the string s.
    :param t: String, the subsequence from which Appleman can build s.
    :return: Integer, the worst-case time for Appleman.
    """
    heap = [(t.count('A'), 0, 0)]  # (best possible length of A, best length so far, length of longest increasing subsequence ending at A)
    for i in range(n):
        if len(heap) == 1 and heap[0][0] < t.count('A'):
            return len(t) - any([c == 'A' for c in t])
        best = heap[0]
        c = t[i]
        if c == 'A':
            pq = [b + 1 for b in [best[0] - 1, heap[0][0]], best[1], best[2]]
            heapq.heapify(pq)
            for b in pq:
                if b >= t.count('A') - i:
                    del heap[0]
                    hp = heapq.heappop(heap)
                    return len(t) - any([b == 'A' for b in t])
        if c == 'B':
            pq = [best[0] + 1, best[1], best[2]]
            heapq.heapify(pq)
            for b in pq:
                if b >= t.count('B') - i:
                    del heap[0]
                    hp = heapq.heappop(heap)
                    return len(t) - any([b == 'B' for b in t])
        if c == 'C':
            pq = [best[0] + 1, best[1] + 1, best[2]]
            heapq.heapify(pq)
            for b in pq:
                if b >= t.count('C') - i:
                    del heap[0]
                    hp = heapq.heappop(heap)
                    return len(t) - any([b == 'C' for b in t])
        if c == 'D':
            pq = [best[0] + 1, best[1] + 1, best[2], best[0] + 1]
            heapq.heapify(pq)
            for b in pq:
                if b >= t.count('D') - i:
                    del heap[0]
                    hp = heapq.heappop(heap)
                    return len(t) - any([b == 'D' for b in t])

    return len(t) - any([c == 'A' for c in t])

