import sys

class Graph:
    def __init__(self, n):
        self.graph = [[] for _ in range(n)]
        self.weights = [-1] * n  # Initialize with -1 to indicate unused edges

    def add_edge(self, v, w):
        self.graph[v-1].append(w-1)
        self.graph[w-1].append(v-1)
        self.weights[v-1] += 1
        self.weights[w-1] += 1

    def get_arrows(self, v):
        return self.graph[v]

    def clean_weight(self, vertex):
        clean_weight = False
        if self.weights[vertex] > 0:
            self.weights[vertex] -= 1
            clean_weight = True
        return clean_weight

    def get_heaviest_unvisited_vertex(self):
        if all(self.weights[i] < 0 for i in range(len(self.weights))):
            return -1
        return -1 if min(self.weights) == 0 else self.weights.index(0)

    def query1(self, vertex):
        clean_weight = self.clean_weight(vertex)
        if vertex == self.get_heaviest_unvisited_vertex():
            vertex = 0

        if not clean_weight:
            return 0

        return min(self.weights)

def solution(n, m, q):
    graph = Graph(n)
    edges = sorted((graph.add_edge(v-1, w-1) for w in range(1, n+1) for v in (w-1 if j < m // 2 else j - m // 2 + n) for j in range(m)))
    for edge in edges:
        graph.add_edge(edge[0], edge[1])

    for _ in range(q):
        query_type, vertex = map(int, input().split())
        if query_type == 1:
            print(graph.query1(vertex))
        else:
            edge = min(graph.get_arrows(vertex) + [i+j for j,v in enumerate(edges) if v[0] == vertex and v[1] != vertex])
            graph.clean_weight(edge[1])

