def count_non_isomorphic_trees(n, d, mod):
    if n < 2:
        return 1 if n == 1 else 0
    total_trees = 0
    for partitions in range(1, n - 1):
        for internal_degree in range(d, 1, -1):
            if internal_degree * (n - partitions) <= d * partitions:
