                    if internal_degree > 1:
                        internal_sum = 1
                        internal_trees = count_non_isomorphic_trees(partitions, d // internal_degree, mod)
                        for extra_internal_distances in range(1, d // internal_degree + 1):
                            internal_trees *= internal_sum
                            internal_sum += internal_trees
                    total_trees += comb(n - partitions, internal_degree) * internal_trees
                    total_trees = total_trees % mod
    return total_trees % mod


