from typing import List

def max_xor_cost(c: List[int], friends: List[int]) -> int:
    n = len(c)
    costs = [c]

    for i in range(1, n):
        costs.append(costs[i - 1] ^ c[i])

    max_cost = 0
    for i in range(n - 1, -1, -1):
        max_cost = max(max_cost, costs[i] - ((1 << i) - (1 << (i + 1))))

    best_spending = max_cost
    for friend in friends:
        current_cost = sum(costs[:friend])
        current_spending = max_cost - current_cost
        if best_spending < current_spending:
            best_spending = current_spending
        for start in range(friend - 1, -1, -1):
            end = min(friend, start + 1)
            while end < n and costs[start] >= costs[end]:
                end += 1
            current_cost = sum(costs[:end])
            current_spending = max_cost - current_cost
            if best_spending < current_spending:
                best_spending = current_spending

    return best_spending

