        self.is_leaf = is_leaf

def count_trees_internal_internal(n, d, mod):
    if d < 2:
        return 1
    if primetest(n):
        return 0

    def is_perfect_d(n, d):
        return n // d % 10000 == 0

    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        for j in range(1, n + 1):
            m = comb(i, j)
            for k in range(1, min(i, j) + 1):
                new_n = j - k
                new_d = j // k - i - j + k + 1
                if is_perfect_d(new_n, new_d):
                    dp[i] = (dp[i] + m * dp[new_n]) % mod
    return dp[n]

